item.stdout:
Bookmarks

Your personal place for links.

Save
No bookmarks yet. Paste a link above to save your first one.<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Bookmarks — prototype</title>
<style>
  :root {
    --bg: #f5f6f8;
    --card: #ffffff;
    --ink: #1d2430;
    --muted: #6b7580;
    --line: #e4e7eb;
    --accent: #2f6fed;
    --accent-ink: #ffffff;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--ink);
  }
  header {
    background: var(--card);
    border-bottom: 1px solid var(--line);
    padding: 18px 24px;
  }
  header h1 { margin: 0; font-size: 20px; }
  header p { margin: 4px 0 0; color: var(--muted); font-size: 13px; }
  main { max-width: 760px; margin: 0 auto; padding: 24px; }

  .saver {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 16px;
    display: flex;
    gap: 10px;
  }
  .saver input {
    flex: 1;
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 11px 12px;
    font-size: 15px;
    outline: none;
  }
  .saver input:focus { border-color: var(--accent); }
  .saver button {
    border: none;
    background: var(--accent);
    color: var(--accent-ink);
    border-radius: 8px;
    padding: 0 20px;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
  }
  .saver button:disabled { opacity: .55; cursor: default; }

  .list { margin-top: 20px; display: flex; flex-direction: column; gap: 14px; }

  .card {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    overflow: hidden;
    display: flex;
    animation: rise .25s ease;
  }
  @keyframes rise { from { opacity: 0; transform: translateY(6px);} to {opacity:1; transform:none;} }
  .card .thumb {
    width: 150px;
    min-width: 150px;
    background: #eef1f5 center/cover no-repeat;
    border-right: 1px solid var(--line);
  }
  .card .body { padding: 14px 16px; flex: 1; min-width: 0; }
  .card .title-row { display: flex; align-items: center; gap: 8px; }
  .card .favicon { width: 16px; height: 16px; border-radius: 3px; flex: none; }
  .card .title { font-size: 16px; font-weight: 600; margin: 0; line-height: 1.3; }
  .card .title a { color: inherit; text-decoration: none; }
  .card .desc { margin: 6px 0 0; color: var(--muted); font-size: 13.5px; line-height: 1.45; }
  .card .host { margin: 10px 0 0; color: var(--muted); font-size: 12px; }

  .empty {
    text-align: center;
    color: var(--muted);
    padding: 60px 20px;
    border: 1px dashed var(--line);
    border-radius: 12px;
    margin-top: 20px;
  }

  .card.pending .body { display: flex; flex-direction: column; justify-content: center; }
  .skeleton { background: #eef1f5; border-radius: 6px; height: 12px; }
  .skeleton.t { height: 16px; width: 55%; margin-bottom: 10px; }
  .skeleton.d { width: 90%; margin-bottom: 6px; }
  .skeleton.d2 { width: 70%; }
  .spin { display:inline-block; width:13px; height:13px; border:2px solid var(--line); border-top-color: var(--accent); border-radius:50%; animation: sp .7s linear infinite; vertical-align:-2px; margin-right:6px;}
  @keyframes sp { to { transform: rotate(360deg);} }
  .fetching { color: var(--muted); font-size: 12px; }
</style>
</head>
<body>
<header>
  <h1>Bookmarks</h1>
  <p>Your personal place for links.</p>
</header>
<main>
  <form class="saver" id="saver" autocomplete="off">
    <input id="url" type="text" placeholder="Paste a link to save…" aria-label="Link to save" />
    <button id="saveBtn" type="submit">Save</button>
  </form>

  <div class="list" id="list"></div>
  <div class="empty" id="empty">No bookmarks yet. Paste a link above to save your first one.</div>
</main>

<script>
// --- Simulated page-detail fetch (prototype only) --------------------------
// A prototype simulates external behaviour. Real fetching would read the live
// page; here we return believable details for a few known links, and derive a
// sensible fallback for anything else.
const CATALOG = {
  "https://martinfowler.com/articles/practical-test-pyramid.html": {
    title: "The Practical Test Pyramid",
    description: "A guide to the test pyramid: how to structure automated tests across unit, service and UI layers for fast, reliable feedback.",
    host: "martinfowler.com",
    favicon: "https://www.google.com/s2/favicons?domain=martinfowler.com&sz=64",
    image: "https://martinfowler.com/articles/practical-test-pyramid/test-pyramid.png"
  },
  "https://en.wikipedia.org/wiki/bookmark_(digital)": {
    title: "Bookmark (digital) — Wikipedia",
    description: "A bookmark is a Uniform Resource Identifier (URI) that is stored for later retrieval in any of various storage formats.",
    host: "en.wikipedia.org",
    favicon: "https://www.google.com/s2/favicons?domain=en.wikipedia.org&sz=64",
    image: ""
  }
};

function fakeFetch(url) {
  const key = url.toLowerCase().replace(/\/+$/,'');
  return new Promise(resolve => {
    setTimeout(() => {
      if (CATALOG[key]) return resolve(CATALOG[key]);
      let host = "";
      try { host = new URL(url).hostname.replace(/^www\./,''); } catch(e) { host = url; }
      const slug = (function(){
        try {
          const p = new URL(url).pathname.split('/').filter(Boolean).pop() || "";
          return decodeURIComponent(p).replace(/[-_]+/g,' ').replace(/\.\w+$/,'');
        } catch(e) { return ""; }
      })();
      resolve({
        title: slug ? (slug.charAt(0).toUpperCase()+slug.slice(1)) : host,
        description: "Saved from " + host + ".",
        host: host,
        favicon: "https://www.google.com/s2/favicons?domain=" + host + "&sz=64",
        image: ""
      });
    }, 900);
  });
}

// --- State -----------------------------------------------------------------
const bookmarks = [];
const listEl = document.getElementById('list');
const emptyEl = document.getElementById('empty');

function normalizeUrl(raw) {
  let u = raw.trim();
  if (!u) return "";
  if (!/^https?:\/\//i.test(u)) u = "https://" + u;
  return u;
}

function render() {
  emptyEl.style.display = bookmarks.length ? "none" : "block";
  listEl.innerHTML = "";
  bookmarks.forEach(b => {
    const card = document.createElement('div');
    card.className = "card" + (b.pending ? " pending" : "");
    if (b.pending) {
      card.innerHTML = `
        <div class="thumb"></div>
        <div class="body">
          <div class="fetching"><span class="spin"></span>Fetching page details…</div>
          <div class="skeleton t" style="margin-top:10px"></div>
          <div class="skeleton d"></div>
          <div class="skeleton d2"></div>
        </div>`;
    } else {
      card.innerHTML = `
        <div class="thumb" style="${b.image ? `background-image:url('${b.image}')` : ''}"></div>
        <div class="body">
          <div class="title-row">
            <img class="favicon" src="${b.favicon}" alt="" onerror="this.style.visibility='hidden'"/>
            <h3 class="title"><a href="${b.url}" target="_blank" rel="noopener">${escapeHtml(b.title)}</a></h3>
          </div>
          <p class="desc">${escapeHtml(b.description)}</p>
          <p class="host">${escapeHtml(b.host)}</p>
        </div>`;
    }
    listEl.appendChild(card);
  });
}

function escapeHtml(s){ return (s||"").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

document.getElementById('saver').addEventListener('submit', async (e) => {
  e.preventDefault();
  const input = document.getElementById('url');
  const btn = document.getElementById('saveBtn');
  const url = normalizeUrl(input.value);
  if (!url) return;
  const entry = { url, pending: true };
  bookmarks.unshift(entry);
  input.value = "";
  btn.disabled = true;
  render();
  const details = await fakeFetch(url);
  Object.assign(entry, details, { pending: false });
  btn.disabled = false;
  render();
});

render();
window.addEventListener('load', () => document.body.setAttribute('data-harness-ready','true'));
</script>
</body>
</html>

