265:            <label>Your tags</label>
267:            <label>Add new</label>
334:          ${b.note ? `<div class="note">${renderMarkdown(b.note)}</div>` : ''}
362:function renderMarkdown(src){
      card.querySelector('[data-act="save"]').addEventListener('click', () => {
        b.title = card.querySelector('.edit-title').value.trim() || b.title;
        b.description = card.querySelector('.edit-desc').value.trim();
        b.edited = true;
        b.editing = false;
        render();
      });
      card.querySelector('[data-act="cancel"]').addEventListener('click', () => {
        b.editing = false; render();
      });
    } else if (b.organizing) {
      card.innerHTML = `
        <div class="thumb" style="${b.image ? `background-image:url('${b.image}')` : ''}"></div>
        <div class="body">
          <div class="editor panel">
            <label>Your tags</label>
            <div class="row suggest-row" id="suggestRow"></div>
            <label>Add new</label>
            <div class="chip-input" id="chipbox">
              <input class="tag-entry" type="text" placeholder="New tag, press Enter…" />
            </div>
            <label>Note <span style="text-transform:none;letter-spacing:0;font-style:italic;">(private · simple Markdown)</span></label>
            <textarea class="note-entry" placeholder="Add a private note… **bold**, *italic*, - lists, [links](url)">${escapeHtml(b.note||'')}</textarea>
            <div class="row">
              <button class="save" data-act="orgsave">Save</button>
              <button class="cancel" data-act="orgcancel">Cancel</button>
            </div>
          </div>
        </div>`;
      const draft = (b.tags || []).slice();
      const existing = allTags();
      const suggestRow = card.querySelector('#suggestRow');
      const chipbox = card.querySelector('#chipbox');
      const entry = card.querySelector('.tag-entry');
      const renderSuggest = () => {
        suggestRow.innerHTML = '';
        existing.forEach(t => {
          const s = document.createElement('span');
          s.className = 'chip suggest' + (draft.includes(t) ? ' on' : '');
          s.textContent = t;
          s.addEventListener('click', () => {
            if (draft.includes(t)) draft.splice(draft.indexOf(t),1); else draft.push(t);
            renderSuggest(); renderNew();
          });
          suggestRow.appendChild(s);
        });
        if (!existing.length) suggestRow.innerHTML = '<span style="color:#6b7580;font-size:12px;">No tags yet — add your first below.</span>';
      };
      const renderNew = () => {
        chipbox.querySelectorAll('.chip').forEach(c => c.remove());
        draft.filter(t => !existing.includes(t)).forEach(t => {
          const s = document.createElement('span'); s.className = 'chip';
          s.innerHTML = `${escapeHtml(t)}<span class="x">×</span>`;
          chipbox.insertBefore(s, entry);
          s.querySelector('.x').addEventListener('click', () => { draft.splice(draft.indexOf(t),1); renderNew(); renderSuggest(); });
        });
      };
      renderSuggest(); renderNew();
      entry.addEventListener('keydown', (ev) => {
        if (ev.key === 'Enter' || ev.key === ',') {
          ev.preventDefault();
          const v = entry.value.trim().replace(/,$/,'');
          if (v && !draft.includes(v)) { draft.push(v); entry.value=''; renderNew(); renderSuggest(); }
        }
      });
      card.querySelector('[data-act="orgsave"]').addEventListener('click', () => {
        const v = entry.value.trim(); if (v && !draft.includes(v)) draft.push(v);
        b.tags = draft; b.note = card.querySelector('.note-entry').value.trim();
        b.organizing = false; render();
      });
      card.querySelector('[data-act="orgcancel"]').addEventListener('click', () => {
        b.organizing = false; render();
      });
    } else {
      card.innerHTML = `
        <div class="thumb" style="${b.image ? `background-image:url('${b.image}')` : ''}"></div>
        <div class="body">
          <div class="title-row">
            <img class="favicon" src="${b.favicon}" alt="" onerror="this.style.visibility='hidden'"/>
            <h3 class="title"><a href="${b.url}" target="_blank" rel="noopener">${escapeHtml(b.title)}</a></h3>
          </div>
          <p class="desc">${escapeHtml(b.description)}</p>
          <p class="host">${escapeHtml(b.host)} ${b.edited ? '<span class="edited-flag">· edited</span>' : ''}</p>
          ${(b.tags && b.tags.length) ? `<div class="tags">${b.tags.map(t=>`<span class="chip">${escapeHtml(t)}</span>`).join('')}</div>` : ''}
          ${b.note ? `<div class="note">${renderMarkdown(b.note)}</div>` : ''}
          <div class="actions">
            <button class="linkbtn" data-act="edit">Edit</button>
            <button class="linkbtn" data-act="organize">${(b.tags&&b.tags.length)||b.note ? 'Tags &amp; note' : 'Add tags &amp; note'}</button>
          </div>
        </div>`;
      card.querySelector('[data-act="edit"]').addEventListener('click', () => {
        bookmarks.forEach(x => { x.editing = false; x.organizing = false; });
        b.editing = true; render();
      });
      card.querySelector('[data-act="organize"]').addEventListener('click', () => {
        bookmarks.forEach(x => { x.editing = false; x.organizing = false; });
        b.organizing = true; render();
      });
    }
    listEl.appendChild(card);
  });

