function escapeHtml(s){ return (s||"").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

function allTags(){
  const set = [];
  bookmarks.forEach(b => (b.tags||[]).forEach(t => { if(!set.includes(t)) set.push(t); }));
  return set.sort((a,b)=>a.localeCompare(b));
}

// Minimal, safe Markdown for notes: escape first, then apply a small subset.
function renderMarkdown(src){
  const lines = (src||"").split(/\r?\n/);
  let html = "", inList = false;
  const inline = (t) => escapeHtml(t)
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[^*])\*([^*]+)\*/g, '$1<em>$2</em>')
    .replace(/`([^`]+)`/g, '<code>$1</code>');
  lines.forEach(line => {
    if (/^\s*[-*]\s+/.test(line)) {
      if (!inList) { html += "<ul>"; inList = true; }
      html += "<li>" + inline(line.replace(/^\s*[-*]\s+/, "")) + "</li>";
    } else {
      if (inList) { html += "</ul>"; inList = false; }
      if (line.trim() === "") html += "";
      else html += "<div>" + inline(line) + "</div>";
    }
  });
  if (inList) html += "</ul>";
  return html;
}

document.getElementById('saver').addEventListener('submit', async (e) => {
  e.preventDefault();
  const input = document.getElementById('url');
  const btn = document.getElementById('saveBtn');
  const url = normalizeUrl(input.value);
  if (!url) return;
  const entry = { url, pending: true };
  bookmarks.unshift(entry);
  input.value = "";
  btn.disabled = true;
  render();
  const details = await fakeFetch(url);
  Object.assign(entry, details, { pending: false });
  btn.disabled = false;
  render();
});

render();
window.addEventListener('load', () => document.body.setAttribute('data-harness-ready','true'));
</script>
</body>
</html>

