// Supports: words, "quoted phrases", #tag, AND / OR / NOT, and ( parentheses ).
// Adjacent terms are combined with implicit AND. Everything is case-insensitive.
function buildMatcher(input) {
  const tokens = [];
  const re = /\s*("[^"]*"|#[^\s()]+|\(|\)|[^\s()]+)/g;
  let m;
  while ((m = re.exec(input)) !== null) tokens.push(m[1]);
  if (!tokens.length) return null;
  let pos = 0;
  const peek = () => tokens[pos];
  const eat = () => tokens[pos++];
  const isOp = (t, op) => t && t.toUpperCase() === op;

  function term(tok) {
    if (tok.startsWith('#')) {
      const name = tok.slice(1).toLowerCase();
      return b => (b.tags||[]).some(tg => tg.toLowerCase() === name);
    }
    let text = tok;
    if (text.length >= 2 && text.startsWith('"') && text.endsWith('"')) text = text.slice(1,-1);
    text = text.toLowerCase();
    if (!text) return () => true;
    return b => haystack(b).includes(text);
  }
  function parseAtom() {
    const t = peek();
    if (t === '(') { eat(); const e = parseOr(); if (peek() === ')') eat(); return e; }
    eat();
    return term(t);
  }
  function parseNot() {
    if (isOp(peek(),'NOT') || peek() === '-') { eat(); const inner = parseNot(); return b => !inner(b); }
    return parseAtom();
  }
  function parseAnd() {
    let left = parseNot();
    while (peek() && !isOp(peek(),'OR') && peek() !== ')') {
      if (isOp(peek(),'AND')) eat();
      const right = parseNot(); const l = left; left = b => l(b) && right(b);
    }
    return left;
  }
  function parseOr() {
    let left = parseAnd();
    while (isOp(peek(),'OR')) { eat(); const right = parseAnd(); const l = left; left = b => l(b) || right(b); }
    return left;
  }
  try { return parseOr(); }
  catch (e) { const q = input.trim().toLowerCase(); return b => haystack(b).includes(q); }
}

