<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Bookmarks — prototype</title>
<style>
  :root {
    --bg: #f5f6f8;
    --card: #ffffff;
    --ink: #1d2430;
    --muted: #6b7580;
    --line: #e4e7eb;
    --accent: #2f6fed;
    --accent-ink: #ffffff;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--ink);
  }
  header {
    background: var(--card);
    border-bottom: 1px solid var(--line);
    padding: 18px 24px;
  }
  header h1 { margin: 0; font-size: 20px; }
  header p { margin: 4px 0 0; color: var(--muted); font-size: 13px; }
  main { max-width: 760px; margin: 0 auto; padding: 24px; }

  .saver {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 16px;
    display: flex;
    gap: 10px;
  }
  .saver input {
    flex: 1;
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 11px 12px;
    font-size: 15px;
    outline: none;
  }
  .saver input:focus { border-color: var(--accent); }
  .saver button {
    border: none;
    background: var(--accent);
    color: var(--accent-ink);
    border-radius: 8px;
    padding: 0 20px;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
  }
  .saver button:disabled { opacity: .55; cursor: default; }

  .notice { margin-top: 12px; background:#eef3ff; border:1px solid #d7e2fb; color:#2554b0; border-radius:9px; padding:10px 12px; font-size:13.5px; display:flex; justify-content:space-between; align-items:center; gap:10px; }
  .notice button { background:none; border:none; color:#2554b0; font-weight:600; cursor:pointer; font-size:13px; }
  .card.flash { animation: flash 1.4s ease; }
  @keyframes flash { 0%,100% { box-shadow:0 0 0 0 rgba(47,111,237,0); } 25% { box-shadow:0 0 0 3px rgba(47,111,237,.35); } }

  .viewbar { margin-top: 18px; display: flex; gap: 6px; border-bottom: 1px solid var(--line); }
  .viewtab {
    background: none; border: none; border-bottom: 2px solid transparent;
    padding: 10px 14px; font-size: 14px; font-weight: 600; color: var(--muted); cursor: pointer;
    margin-bottom: -1px;
  }
  .viewtab.on { color: var(--accent); border-bottom-color: var(--accent); }
  .viewtab .count { font-weight: 500; color: var(--muted); font-size: 12px; margin-left: 5px; }

  .finder { margin-top: 16px; }
  .finder #search {
    width: 100%; border: 1px solid var(--line); border-radius: 10px;
    padding: 12px 14px; font-size: 15px; outline: none; background: #fff;
  }
  .finder #search:focus { border-color: var(--accent); }
  .searchhint { margin-top: 7px; color: var(--muted); font-size: 12px; }
  .searchhint code { background: #eef1f5; border-radius: 4px; padding: 1px 5px; font-size: 11.5px; }
  .filterbar { margin-top: 12px; display: flex; flex-wrap: wrap; gap: 7px; align-items: center; }
  .filterbar .flabel { font-size: 12px; color: var(--muted); margin-right: 2px; }
  .filter-chip {
    background: #f3f4f6; color: #444; border: 1px solid var(--line);
    border-radius: 999px; padding: 4px 11px; font-size: 12.5px; cursor: pointer;
  }
  .filter-chip.on { background: var(--accent); color: #fff; border-color: var(--accent); }
  .clearf { font-size: 12px; color: var(--accent); cursor: pointer; background:none; border:none; font-weight:600; }
  .resultmeta { margin-top: 16px; color: var(--muted); font-size: 12.5px; min-height: 16px; }

  .list { margin-top: 8px; display: flex; flex-direction: column; gap: 14px; }

  .card {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    overflow: hidden;
    display: flex;
    animation: rise .25s ease;
  }
  @keyframes rise { from { opacity: 0; transform: translateY(6px);} to {opacity:1; transform:none;} }
  .card .thumb {
    width: 150px;
    min-width: 150px;
    background: #eef1f5 center/cover no-repeat;
    border-right: 1px solid var(--line);
  }
  .card .body { padding: 14px 16px; flex: 1; min-width: 0; }
  .card .title-row { display: flex; align-items: center; gap: 8px; }
  .card .favicon { width: 16px; height: 16px; border-radius: 3px; flex: none; }
  .card .title { font-size: 16px; font-weight: 600; margin: 0; line-height: 1.3; }
  .card .title a { color: inherit; text-decoration: none; }
  .card .desc { margin: 6px 0 0; color: var(--muted); font-size: 13.5px; line-height: 1.45;
    display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
  .card .title { overflow-wrap: anywhere; }
  .card .host { margin: 10px 0 0; color: var(--muted); font-size: 12px; }
  .badge { font-size: 11px; font-weight: 600; border-radius: 999px; padding: 2px 9px; flex: none; }
  .badge.readlater { background: #fff3e0; color: #b0621a; border: 1px solid #f6ddb8; }
  .badge.archived { background: #eef0f2; color: #667080; border: 1px solid #dfe3e8; }
  .linkbtn.muted { color: var(--muted); }

  .card .actions { margin-top: 10px; display: flex; gap: 12px; }
  .linkbtn {
    background: none; border: none; padding: 0; cursor: pointer;
    color: var(--accent); font-size: 12.5px; font-weight: 600;
  }
  .editor { margin-top: 4px; }
  .editor label { display:block; font-size: 11px; color: var(--muted); margin: 8px 0 3px; text-transform: uppercase; letter-spacing:.03em;}
  .editor input, .editor textarea {
    width: 100%; border: 1px solid var(--line); border-radius: 7px;
    padding: 8px 9px; font-size: 14px; font-family: inherit; outline: none;
  }
  .editor input:focus, .editor textarea:focus { border-color: var(--accent); }
  .editor textarea { resize: vertical; min-height: 54px; }
  .editor .row { display:flex; gap:8px; margin-top: 12px; }
  .editor .row button { border-radius:7px; padding:7px 14px; font-size:13px; font-weight:600; cursor:pointer; border:1px solid var(--line);}
  .editor .save { background: var(--accent); color:#fff; border-color: var(--accent);}
  .editor .cancel { background:#fff; color: var(--ink); }
  .edited-flag { color: var(--muted); font-size: 11px; font-style: italic; }

  .tags { margin-top: 10px; display: flex; flex-wrap: wrap; gap: 6px; }
  .chip {
    background: #eef3ff; color: #2554b0; border: 1px solid #d7e2fb;
    border-radius: 999px; padding: 3px 10px; font-size: 12px; display:inline-flex; align-items:center; gap:6px;
  }
  .chip .x { cursor: pointer; font-weight: 700; color: #6f8bc7; }
  .note {
    margin-top: 10px; background: #fffdf3; border: 1px solid #efe6c4;
    border-radius: 8px; padding: 9px 11px; font-size: 13px; color: #5f5636; white-space: pre-wrap;
  }
  .panel { margin-top: 4px; }
  .panel .chip-input { display:flex; flex-wrap:wrap; gap:6px; border:1px solid var(--line); border-radius:7px; padding:6px; }
  .panel .chip-input input { border:none; outline:none; flex:1; min-width:120px; font-size:14px; padding:3px; }
  .row { display:flex; flex-wrap:wrap; gap:6px; }
  .chip.suggest { background:#f3f4f6; color:#444; border-color:#e4e7eb; cursor:pointer; }
  .chip.suggest.on { background:#eef3ff; color:#2554b0; border-color:#d7e2fb; }
  .note ul { margin:4px 0; padding-left:20px; }

